\documentclass[11pt]{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage{lmodern}
\usepackage{amsmath,amssymb,amsthm,mathtools}
\usepackage{microtype}
\usepackage[hidelinks]{hyperref}
\usepackage[margin=1in]{geometry}
\usepackage{enumitem}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\theoremstyle{remark}
\newtheorem{remark}[theorem]{Remark}
\newcommand{\Prop}{\mathsf{Prop}}
\newcommand{\self}{\mathsf{self}}
\title{Recursive Presentation, Diagonal Obstruction,\\and Finite Reflective Hierarchies}
\author{Aristotle}
\date{July 20, 2026}
\begin{document}
\maketitle

\begin{abstract}
Self-reference is often treated as if it automatically produced undecidability. We separate recursive dependent-product presentations, complete semantic self-models, and rank-stratified reflective syntax. A presentation $T\cong\prod_{x\in T}P(x)$ need not cause undecidability: the one-element type with the constantly true predicate has such a presentation and decidable equality. A semantic self-model assigns to each $t\in T$ a predicate on $T$; diagonal negation proves that no such assignment names every predicate. More generally, surjective naming of all $B$-valued observations forces every endomorphism of $B$ to have a fixed point. Finally, a syntax with atoms, Boolean operations, universal and existential layers, and a self-binder carries a natural-number rank and De Morgan duality. Duality preserves rank, and canonical alternating towers have rank $n$ at level $n$. This locates the boundary between benign recursive shape and impossible complete self-knowledge, and explains why comparisons with the Church--Kleene ordinal should concern effective closure ordinals rather than cardinalities of unrestricted collections of types.
\end{abstract}

\section{Introduction}
Recursive descriptions occur throughout logic, computation, semantics, and theories of self-modeling systems. A type may be described using functions whose domain is that same type; a program may inspect representations of programs; a language may contain expressions about expressions. These constructions invite the intuition that self-reference itself forces undecidability.

That intuition combines distinct hypotheses. The equation
\[
T\cong\prod_{x\in T}P(x)
\]
asserts one reversible presentation of $T$. It does not assert that elements of $T$ name all predicates on $T$. By contrast, an inspection map $I:T\to(T\to\Prop)$ is semantically complete only if it is surjective. This stronger condition supports diagonalization.

Alternating universal and existential layers also produce finite ranks analogous in shape to familiar logical hierarchies. An explicit self-binder can count as another recursive layer. This gives an unbounded hierarchy indexed by the natural numbers, but a syntactic rank theorem is not a semantic strictness theorem. Nor does it identify a cardinality of types with the Church--Kleene ordinal, which measures computable well-order types.

Our results are: recursive presentation alone does not force undecidability; every propositional self-model omits its diagonal predicate; complete $B$-valued observation forces fixed points for all maps $B\to B$; duality preserves reflective rank; and alternating towers witness every finite rank.

\section{Recursive dependent-product presentations}

\begin{definition}
Let $T$ be a type and $P:T\to\Prop$ a predicate. A \emph{recursive dependent-product presentation} of $T$ consists of $P$ and an equivalence
\[
U:T\simeq\prod_{x\in T}P(x).
\]
The repeated occurrence of $T$ records recursive shape. No effectiveness or semantic completeness is assumed.
\end{definition}

A type has \emph{decidable equality} when there is a Boolean comparison $e:T\times T\to\{0,1\}$ satisfying $e(x,y)=1$ exactly when $x=y$.

\begin{theorem}[Finite counterexample]
There exists a type $T$ with a recursive dependent-product presentation and decidable equality.
\end{theorem}
\begin{proof}
Let $T=\{\star\}$ and let $P(\star)$ be true. The dependent product has exactly one element, so it is equivalent to $T$. Define $e(x,y)=1$ for every pair. Since every two elements of a singleton are equal, this decides equality.
\end{proof}

Thus the implication
\[
\left(T\simeq\prod_{x\in T}P(x)\right)\Longrightarrow
\text{equality on $T$ is undecidable}
\]
is false without additional hypotheses. The equivalence unfolds elements according to one selected family $P$; it does not enumerate the entire predicate space $T\to\Prop$.

\section{Semantic self-models and diagonal omission}

\begin{definition}
A \emph{propositional semantic self-model} on $T$ is a map
\[
I:T\to(T\to\Prop).
\]
It is \emph{complete} when it is surjective: for every predicate $Q:T\to\Prop$, some $t\in T$ satisfies $I(t)=Q$.
\end{definition}

\begin{definition}
The \emph{diagonal predicate} of $I$ is
\[
D_I(x)=\neg I(x)(x).
\]
\end{definition}

\begin{theorem}[Diagonal omission]
For every propositional semantic self-model $I$ and every $t\in T$,
\[
I(t)\ne D_I.
\]
Hence $D_I$ is absent from the image of $I$.
\end{theorem}
\begin{proof}
If $I(t)=D_I$, evaluation at $t$ gives
\[
I(t)(t)=D_I(t)=\neg I(t)(t),
\]
which is impossible. The argument applies to every $t$.
\end{proof}

\begin{corollary}[No complete propositional self-model]
No type, finite or infinite, admits a complete propositional semantic self-model.
\end{corollary}
\begin{proof}
Completeness would provide $t$ with $I(t)=D_I$, contradicting diagonal omission.
\end{proof}

The finite counterexample and diagonal theorem establish a strict separation: recursive presentation may exist, while complete predicate naming cannot. The obstruction is not recursion alone but exhaustive naming combined with self-application.

\section{Complete observations force fixed points}

Let $T$ be a code space, $B$ a space of values, and $N:T\to(T\to B)$ a naming system.

\begin{theorem}[Complete observation fixed-point theorem]
If $N$ is surjective, then every transformation $g:B\to B$ has a fixed point. That is, there exists $b\in B$ such that $g(b)=b$.
\end{theorem}
\begin{proof}
Define $h:T\to B$ by $h(x)=g(N(x)(x))$. Choose $t$ with $N(t)=h$, using surjectivity, and put $b=N(t)(t)$. Evaluation at $t$ yields
\[
b=N(t)(t)=h(t)=g(N(t)(t))=g(b).
\]
\end{proof}

\begin{corollary}[Fixed-point-free obstruction]
If $B$ admits a fixed-point-free endomorphism, no surjective naming system $T\to(T\to B)$ exists.
\end{corollary}

Boolean negation recovers the propositional result. The cyclic shift $b\mapsto b+1\pmod 3$ gives another example on three values.

For a finite Boolean table with rows and columns indexed by $0,\ldots,n-1$, the omitted predicate is computed by complementing the main diagonal:
\[
D(i)=1-N(i,i).
\]
This requires $O(n)$ time and $O(n)$ output space. Row $i$ differs from $D$ at column $i$, so no row equals $D$.

\section{Reflective syntax}

Fix a type $A$ of atomic labels.

\begin{definition}[Reflective codes]
The set $\mathcal R(A)$ is generated by atomic codes $\operatorname{atom}(a)$, constants $\top$ and $\bot$, conjunction $C\wedge D$, negation $\neg C$, quantified codes $\forall C$ and $\exists C$, and a self-binding code $\self(C)$.
\end{definition}

The universal polarity $\mathsf U$ and existential polarity $\mathsf E$ are dual:
\[
\mathsf U^\perp=\mathsf E,
\qquad
\mathsf E^\perp=\mathsf U.
\]

\begin{lemma}[Involutive polarity duality]
For each polarity $p$, $(p^\perp)^\perp=p$.
\end{lemma}
\begin{proof}
There are two cases, and each swap is reversed by the second swap.
\end{proof}

\begin{definition}[Reflective rank]
Define $r:\mathcal R(A)\to\mathbb N$ recursively by
\[
\begin{aligned}
r(\operatorname{atom}(a))&=r(\top)=r(\bot)=0,\\
r(C\wedge D)&=\max\{r(C),r(D)\},\qquad r(\neg C)=r(C),\\
r(\forall C)&=r(\exists C)=r(C)+1,\\
r(\self(C))&=r(C)+1.
\end{aligned}
\]
Thus quantification and self-binding add layers, whereas negation is rank-neutral.
\end{definition}

\begin{definition}[Dual code]
Define $C\mapsto C^*$ by
\[
\begin{aligned}
\operatorname{atom}(a)^*&=\neg\operatorname{atom}(a),\\
\top^*&=\bot,\qquad \bot^*=\top,\\
(C\wedge D)^*&=\neg(C^*\wedge D^*),\\
(\neg C)^*&=C,\\
(QC)^*&=Q^\perp(C^*),\\
\self(C)^*&=\self(C^*).
\end{aligned}
\]
\end{definition}

\begin{theorem}[Rank preservation under duality]
For every reflective code $C$,
\[
r(C^*)=r(C).
\]
\end{theorem}
\begin{proof}
Use structural induction. Atomic and constant cases have rank zero. For conjunction, the induction hypotheses preserve the two branch ranks, the maximum is unchanged, and outer negation adds nothing. For negation, its removal is rank-neutral. For a quantified code, duality swaps polarity while either quantifier adds one. For a self-binder, both sides add one to equal inner ranks.
\end{proof}

Thus duality moves within each rank stratum while exchanging universal and existential polarity.

\section{Canonical alternating towers}

Fix $a\in A$ and define
\[
C_0=\operatorname{atom}(a),
\qquad
C_{n+1}=Q_nC_n,
\]
where
\[
Q_n=\begin{cases}
\forall,&n\text{ even},\\
\exists,&n\text{ odd}.
\end{cases}
\]
The sequence begins
\[
\operatorname{atom}(a),\quad
\forall\operatorname{atom}(a),\quad
\exists\forall\operatorname{atom}(a),\quad
\forall\exists\forall\operatorname{atom}(a),\ldots
\]

\begin{theorem}[Exact rank of alternating towers]
For every $n\in\mathbb N$, $r(C_n)=n$.
\end{theorem}
\begin{proof}
The base atom has rank zero. If $r(C_n)=n$, the next code adds one quantifier, independently of polarity, so $r(C_{n+1})=n+1$.
\end{proof}

\begin{corollary}[Distinct levels]
If $C_m=C_n$, then $m=n$; hence $n\mapsto C_n$ is injective.
\end{corollary}
\begin{proof}
Equal codes have equal ranks, and the preceding theorem identifies those ranks with $m$ and $n$.
\end{proof}

\begin{corollary}[Unbounded finite rank]
For every $n$, there exists a reflective code of rank greater than $n$.
\end{corollary}
\begin{proof}
Take $C_{n+1}$.
\end{proof}

\begin{theorem}[Hierarchy--diagonal boundary]
Every finite rank is inhabited by a reflective code, while every propositional semantic self-model omits a predicate. Explicitly, for every $n$ there is $C$ with $r(C)=n$; and for every $I:T\to(T\to\Prop)$ there is $D:T\to\Prop$ such that $I(t)\ne D$ for all $t$.
\end{theorem}
\begin{proof}
Use $C_n$ for the first statement and $D(x)=\neg I(x)(x)$ for the second.
\end{proof}

The tower generator uses $O(n)$ time and output space. Rank and dualization each require one traversal of a syntax tree: for $N$ nodes and height $h$, they take $O(N)$ time and $O(h)$ recursive stack space.

\section{Interpretation and applications}
A system may possess a recursive presentation and increasingly nested reflective descriptions without possessing a complete map of all predicates about itself. Therefore $T\simeq\prod_{x\in T}P(x)$ is neither a definition of consciousness nor a proof of undecidability. Effectiveness, naturality, expressive completeness, and semantic interpretation are separate assumptions.

In reflective programming and query languages, the fixed-point obstruction rules out unrestricted internal names for every observation into a value space with a fixed-point-free operation. Reflection itself need not be abandoned; it can be stratified through typed stages, restricted quotation, positivity, or partial semantics.

A finite classifier table gives a concrete application. Row $i$ records classifier $i$ on all inputs. Complementing entry $(i,i)$ constructs a target vector that defeats classifier $i$ on input $i$. This is an abstract adversarial principle obtained coordinate by coordinate.

The rank filtration can organize induction, bounded search, normalization, and visualization. Yet rank difference alone does not prove semantic separation. Strict expressive hierarchy requires an interpretation and predicates separating adjacent levels.

\section{The Church--Kleene boundary}
The Church--Kleene ordinal $\omega_1^{\mathrm{CK}}$ is the supremum of the computable ordinals. It is an order type bounding effective well-order notations. By contrast, the unrestricted collection of self-referential types has no canonical universe-independent cardinality. Equating that cardinality with $\omega_1^{\mathrm{CK}}$ therefore confuses two categories of size.

The hierarchy proved here has order type $\omega$: one canonical rank for each natural number. It does not enumerate all computable ordinals. A meaningful transfinite extension begins with positive effective recursive operators. Positivity can produce monotonicity, making transfinite iteration possible. The first stage at which such an iteration stabilizes is its closure ordinal.

A corrected conjectural direction is that closure ordinals of finitely generated positive effective reflective codes are cofinal in $\omega_1^{\mathrm{CK}}$ but never attain it. This compares ordinals with ordinals. The present finite-rank results do not prove that conjecture; they provide the base filtration, rank-preserving duality, and the warning that negative self-occurrence enables diagonal obstruction.

\section{Limitations and future work}
The finite counterexample concerns recursive presentation under exactly the stated hypothesis; stronger assumptions require new results. The hierarchy is syntactic, not a proof of strict semantic expressiveness. The self-model impossibility assumes total naming and unrestricted diagonal evaluation. No claim is made that consciousness is characterized by these structures.

Future work should construct semantics for positive reflective codes and determine their closure ordinals; seek effective universal predicates separating adjacent finite levels; test whether naturality under automorphisms bridges recursive presentation and semantic inspection; and classify observation spaces by fixed-point-free endomorphisms. Closure ordinals, rather than raw cardinalities, offer the coherent route toward $\omega_1^{\mathrm{CK}}$.

\section{Conclusion}
Self-reference has several mathematical forms. Recursive dependent-product presentation can be finite and decidable. Complete predicate naming is impossible because the diagonal predicate escapes. Complete general observation forces fixed points in the value space. Independently, reflective syntax has a natural rank, a rank-preserving universal--existential duality, and canonical codes at every finite level.

The boundary is exact: recursive shape alone is benign; exhaustive self-observation is obstructed; and finite reflective complexity is unbounded but remains syntactic. This separation provides a sound basis for studying effective positive recursion and transfinite closure without unsupported conclusions about undecidability, semantic completeness, or cardinalities of self-referential types.
\end{document}

