from __future__ import annotations

def alternating_tower(level: int, atom: str = "a") -> str:
    if level < 0:
        raise ValueError("level must be nonnegative")
    code = atom
    for n in range(level):
        quantifier = "∀" if n % 2 == 0 else "∃"
        code = f"{quantifier}({code})"
    return code

def main() -> None:
    for level in range(10):
        code = alternating_tower(level)
        computed_rank = code.count("∀") + code.count("∃")
        assert computed_rank == level
        print(f"level={level:2d} rank={computed_rank:2d} code={code}")

if __name__ == "__main__":
    main()

