def rank(code: Code) -> int:
    if code.kind in {"atom", "truth", "falsity"}:
        return 0
    if code.kind == "neg":
        return rank(code.children[0])
    if code.kind == "conj":
        return max(rank(code.children[0]), rank(code.children[1]))
    if code.kind in {"forall", "exists", "self"}:
        return rank(code.children[0]) + 1
    raise ValueError(code.kind)

from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class Code:
    kind: str
    label: str = ""
    children: tuple["Code", ...] = ()

def dual(code: Code) -> Code:
    if code.kind == "atom":
        return Code("neg", children=(code,))
    if code.kind == "truth":
        return Code("falsity")
    if code.kind == "falsity":
        return Code("truth")
    if code.kind == "neg":
        return code.children[0]
    if code.kind == "conj":
        left, right = code.children
        return Code("neg", children=(Code("conj", children=(dual(left), dual(right))),))
    if code.kind in {"forall", "exists"}:
        opposite = "exists" if code.kind == "forall" else "forall"
        return Code(opposite, children=(dual(code.children[0]),))
    if code.kind == "self":
        return Code("self", children=(dual(code.children[0]),))
    raise ValueError(code.kind)

