#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
from random import Random

def main() -> None:
    n, cell = 12, 32
    rng = Random(20260720)
    table = [[rng.randrange(2) for _ in range(n)] for _ in range(n)]
    diagonal = [1 - table[i][i] for i in range(n)]
    colors = {0: "#e8eef8", 1: "#325d9b"}
    parts = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{(n+2)*cell}" height="{(n+2)*cell}">',
             '<rect width="100%" height="100%" fill="#fbfcff"/>']
    for i, row in enumerate(table):
        for j, value in enumerate(row):
            stroke = "#ef8354" if i == j else "#ffffff"
            parts.append(f'<rect x="{j*cell}" y="{i*cell}" width="{cell}" height="{cell}" fill="{colors[value]}" stroke="{stroke}" stroke-width="3"/>')
    for i, value in enumerate(diagonal):
        parts.append(f'<rect x="{(n+1)*cell}" y="{i*cell}" width="{cell}" height="{cell}" fill="{colors[value]}" stroke="#2a9d8f" stroke-width="3"/>')
    parts.append('</svg>')
    Path("diagonal_omission.svg").write_text("".join(parts))

if __name__ == "__main__": main()

